void pg_icon(pg_canvas *c,pg_icon_id id,int x,int y,int scale,uint32_t color){
    if(!c||!c->pixels||id<0||id>=PG_ICON_COUNT||scale<1||scale>8)return;
    int n=scale==1?16:32,side=16*scale,left=x-side/2,top=y-side/2;
    for(int row=0;row<n;++row){
        uint32_t bits=n==16?sprites16[id][row]:sprites32[id][row];
        int y0=top+row*side/n,y1=top+(row+1)*side/n;
        /* Emit contiguous runs; 32px control outlines cost fewer draw calls. */
        for(int col=0;col<n;){
            if(!(bits&(1u<<(n-1-col)))){++col;continue;}
            int start=col++;
            while(col<n&&(bits&(1u<<(n-1-col))))++col;
            int x0=left+start*side/n,x1=left+col*side/n;
            pg_rect(c,x0,y0,x1-x0,y1-y0,color);
        }
    }
}
